def ref_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))

@given(base=st.integers(min_value=2, max_value=9))
def test_zero_for_all_bases(base):
    assert change_base(0, base) == "0"
